Ring_Get_0400:
	ldb w, 0x00                                          ; F8405D  20 00
	ld ix, (xhl-8)                                       ; F8405F  9b f8 24
	m_cp_rm MWD+r3, 0xfc, r4                             ; F84062  9b fc f4
