	.byte 0x00			; F9083A  index 1
	.byte 0x00			; F9083B  index 2
	.byte 0x7F			; F9083C  index 3
	.byte 0x3F			; F9083D  index 4
	.byte 0x1F			; F9083E  index 5
	.byte 0x0F			; F9083F  index 6
	.byte 0x07			; F90840  index 7
	.byte 0x03			; F90841  index 8

