	and XBC,XBC                                          ; FC8053  e9 c1
	jr z, .LFC8063                                       ; FC8055  66 0c
	lda_24 xiy, (0xfcbf39)                               ; FC8057  f2 39 bf fc 35
	lda_24 xix, (0x602054)                               ; FC805C  f2 54 20 60 34
	ldir85                                               ; FC8061  85 11
.LFC8063:
