	and XBC,XBC                                          ; FC8068  e9 c1
	jr z, .LFC807C                                       ; FC806A  66 10
	lda_24 xix, (0x602000)                               ; FC806C  f2 00 20 60 34
	xor WA,WA                                            ; FC8071  d8 d0
.LFC8073:
